('fund', 'الصندوق العربي للإنماء الاقتصادي والاجتماعي', 'Arab Fund for Economic and Social Development', 'all', 'all', 'مؤسسة مالية عربية تموّل مشاريع البنية والتنمية الاقتصادية والاجتماعية، مع أولوية للمشاريع العربية المشتركة.', 'حكومات ومشاريع عامة وخاصة في الدول الأعضاء في جامعة الدول العربية.', NULL, NULL, 'USD', 'loan', 'https://www.arabfund.org', TRUE, TRUE, 495),
('fund', 'صندوق النقد العربي', 'Arab Monetary Fund', 'all', 'all', 'يموّل موازين مدفوعات الدول العربية ويدعم الإصلاحات النقدية وتطوير الأسواق المالية والتجارة البينية.', 'الدول العربية الأعضاء (22 دولة) ومؤسساتها المالية وفق برامج الصندوق.', NULL, NULL, 'USD', 'loan', 'https://www.amf.org.ae', TRUE, TRUE, 496)
) AS v(type, name_ar, name_en, country_code, sector, description, eligibility, min_amount, max_amount, currency, financing_type, website, is_active, is_featured, sort_order)
