  WHERE existing.country_code = v.country_code AND existing.name_en = v.name_en
);

INSERT INTO public.funding_sources (
  type, name_ar, name_en, country_code, sector, description, eligibility,
  min_amount, max_amount, currency, financing_type, website, is_active, is_featured, sort_order
)
SELECT v.type, v.name_ar, v.name_en, v.country_code, v.sector, v.description, v.eligibility, v.min_amount::numeric, v.max_amount::numeric, v.currency, v.financing_type, v.website, v.is_active, v.is_featured, v.sort_order FROM (VALUES
('fund', 'أجفند', 'AGFUND', 'all', 'all', 'مؤسسة تنموية خليجية تموّل برامج التنمية البشرية والتمويل الأصغر، خاصة النساء والأطفال، بالشراكة مع منظمات أممية ومحلية.', 'برامج ومؤسسات تمويل أصغر وتنمية بشرية في الدول العربية والنامية.', NULL, NULL, 'USD', 'loan', 'https://agfund.org', TRUE, TRUE, 497),
('fund', 'المصرف العربي للتنمية الاقتصادية في أفريقيا', 'BADEA', 'all', 'all', 'يموّل التنمية في الدول الأفريقية غير العربية ويدعم التجارة العربية الأفريقية بتمويل من دول الجامعة العربية.', 'مشاريع في أفريقيا غير العربية، وتمويل تجارة يشمل دولاً عربية أفريقية وفق سياسات المصرف.', NULL, NULL, 'USD', 'loan', 'https://www.badea.org', TRUE, TRUE, 498),
('fund', 'ابيكورب', 'APICORP', 'all', 'energy,industry', 'شركة مالية متعددة الأطراف لأوابك تموّل مشاريع الطاقة والصناعة والتجارة المرتبطة بهما في الدول العربية الأعضاء.', 'مشاريع طاقة وصناعة في الدول العربية الأعضاء في أوابك وشركائها.', NULL, NULL, 'USD', 'loan', 'https://www.apicorp.org', TRUE, TRUE, 499),
('fund', 'صندوق أوبك للتنمية الدولية', 'OPEC Fund', 'all', 'all', 'صندوق تنمية متعدد الأطراف يموّل البنية والمشاريع الخاصة في الدول النامية، ومنها دول عربية غير أعضاء في أوبك.', 'حكومات وشركات في الدول النامية المؤهلة، بما فيها دول عربية.', NULL, NULL, 'USD', 'loan', 'https://opecfund.org', TRUE, TRUE, 500),
('fund', 'مؤسسة التمويل الدولية', 'IFC', 'all', 'all', 'ذراع القطاع الخاص لمجموعة البنك الدولي: قروض ومساهمات وضمانات للشركات والبنوك في الأسواق الناشئة.', 'شركات خاصة وبنوك في الدول العربية التي تعمل فيها مجموعة البنك الدولي.', NULL, NULL, 'USD', 'equity', 'https://www.ifc.org', TRUE, TRUE, 501),
('fund', 'البنك الأوروبي لإعادة الإعمار والتنمية', 'EBRD', 'all', 'all', 'يموّل القطاع الخاص والبنية في اقتصادات التحول، ومن بينها مصر والأردن والمغرب وتونس ولبنان وفلسطين.', 'شركات ومشاريع في دول عمليات البنك، وليست كل الدول العربية ضمن نطاقه.', NULL, NULL, 'USD', 'loan', 'https://www.ebrd.com', TRUE, TRUE, 502),
('fund', 'أفريكسيم بنك', 'Afreximbank', 'all', 'trade', 'بنك تجارة أفريقي يموّل التجارة داخل أفريقيا ومع الخارج، ويشمل الدول العربية الأفريقية الأعضاء.', 'بنوك ومصدّرون ومستوردون في الدول الأفريقية الأعضاء، ومنها مصر والمغرب وتونس والجزائر والسودان وموريتانيا وجيبوتي والصومال وجزر القمر.', NULL, NULL, 'USD', 'loan', 'https://www.afreximbank.com', TRUE, TRUE, 503),
('fund', 'بنك الاستثمار الأوروبي', 'European Investment Bank', 'all', 'all', 'ذراع الإقراض للاتحاد الأوروبي يموّل مشاريع في دول الجوار الجنوبي العربية المتوسطية إضافة إلى عملياته الأوروبية.', 'مشاريع في مصر والأردن والمغرب وتونس ولبنان وفلسطين وفق تفويض الجوار، وليست كل الدول العربية.', NULL, NULL, 'USD', 'loan', 'https://www.eib.org', TRUE, TRUE, 504),
('fund', 'المؤسسة العربية لضمان الاستثمار وائتمان الصادرات', 'Dhaman', 'all', 'all', 'مؤسسة عربية متعددة الأطراف تؤمّن الاستثمار ضد المخاطر السياسية وائتمان الصادرات ضد المخاطر التجارية في الدول العربية.', 'مستثمرون ومصدّرون ومؤسسات مالية في الدول العربية الأعضاء أو المتجهة إليها.', NULL, NULL, 'USD', 'guarantee', 'https://www.dhaman.org', TRUE, TRUE, 505),
('fund', 'برنامج تمويل التجارة العربية', 'Arab Trade Finance Program', 'all', 'trade', 'برنامج مشترك لصندوق النقد العربي والصندوق العربي يموّل التجارة العربية البينية عبر خطوط للبنوك المعتمدة.', 'بنوك معتمدة ومصدّرون/مستوردون عرب لسلع ذات منشأ عربي.', NULL, NULL, 'USD', 'loan', 'https://atfp.org.ae', TRUE, TRUE, 506),
('fund', 'الهيئة العربية للاستثمار والإنماء الزراعي', 'AAAID', 'all', 'agriculture,food_manufacturing', 'هيئة عربية تستثمر في الشركات والمشاريع الزراعية والغذائية لتعزيز الأمن الغذائي في الدول المساهمة.', 'مشاريع زراعية وغذائية في الدول العربية المساهمة (19 دولة).', NULL, NULL, 'USD', 'equity', 'https://www.aaaid.org', TRUE, TRUE, 507),
('fund', 'البنك الدولي', 'World Bank', 'all', 'all', 'يموّل الحكومات ومشاريع التنمية، ويموّل القطاع الخاص عبر مؤسسات المجموعة، من خلال مكاتب قطرية في عواصم عربية.', 'حكومات ومشاريع وفق نافذة كل دولة عربية تتعامل مع البنك.', NULL, NULL, 'USD', 'loan', 'https://www.worldbank.org', TRUE, TRUE, 508),
('fund', 'البنك الأفريقي للتنمية', 'African Development Bank', 'all', 'all', 'يموّل التنمية والقطاع الخاص في الدول الأفريقية الأعضاء، ومنها الدول العربية في أفريقيا.', 'حكومات وشركات في الدول الأفريقية الأعضاء: مصر، المغرب، تونس، الجزائر، السودان، موريتانيا، جيبوتي، الصومال، جزر القمر.', NULL, NULL, 'USD', 'loan', 'https://www.afdb.org', TRUE, TRUE, 509),
('fund', 'صندوق التضامن الإسلامي للتنمية', 'Islamic Solidarity Fund for Development', 'all', 'all', 'صندوق مكافحة الفقر داخل مجموعة البنك الإسلامي للتنمية يقدّم تمويلاً ميسّراً وبرامج تنمية بشرية في الدول الأعضاء الأشد حاجة.', 'دول أعضاء منخفضة الدخل وبرامج مكافحة الفقر عبر نافذة البنك الإسلامي للتنمية.', NULL, NULL, 'USD', 'loan', 'https://isfd.isdb.org', TRUE, TRUE, 510)
) AS v(type, name_ar, name_en, country_code, sector, description, eligibility, min_amount, max_amount, currency, financing_type, website, is_active, is_featured, sort_order)
WHERE NOT EXISTS (
  SELECT 1 FROM public.funding_sources existing
  WHERE existing.country_code = v.country_code AND existing.name_en = v.name_en
);
